      fullName: {
        id: "full-name",
        label: "Full name",
        type: "text",
        name: "fullName",
        autocomplete: "name",
        required: true,
        placeholder: "Jordan Lee"
      },
      email: {
        id: "email-address",
        label: "Email address",
        type: "email",
        name: "email",
        autocomplete: "email",
