  <script>
    const fieldConfig = {
      fullName: {
        id: "full-name",
        label: "Full name",
        type: "text",
        name: "fullName",
        autocomplete: "name",
        required: true,
        placeholder: "Jordan Lee"
      },
      email: {
        id: "email-address",
        label: "Email address",
        type: "email",
        name: "email",
        autocomplete: "email",
        required: true,
        placeholder: "jordan@example.com"
      },
      phone: {
        id: "phone-number",
        label: "Phone number",
        type: "tel",
        name: "phone",
        autocomplete: "tel",
        required: false,
        placeholder: "(555) 123-4567",
        helpText: "Optional. Use digits with spaces, dashes, or parentheses, for example (555) 123-4567 or +1 555 123 4567."
      }
    };

    function escapeHtml(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function FormField(config) {
      const helpId = config.helpText ? `${config.id}-help` : "";
      const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";
      const requiredMarkup = config.required
        ? '<span class="required-indicator" aria-hidden="true"> *</span><span class="sr-only"> required</span>'
        : ' <span class="field-hint">(optional)</span>';

      return `
        <div class="form-field">
          <label for="${config.id}">${config.label}${requiredMarkup}</label>
          <input
            id="${config.id}"
            name="${config.name}"
            type="${config.type}"
            ${config.required ? "required" : ""}
            autocomplete="${config.autocomplete}"
            placeholder="${escapeHtml(config.placeholder)}"${describedBy}
          >
          ${config.helpText ? `<p class="field-hint" id="${helpId}">${config.helpText}</p>` : ""}
          <p class="error-message" id="${config.id}-error" hidden></p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <form id="support-form" novalidate>
          <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
          ${FormField(fieldConfig.fullName)}
          ${FormField(fieldConfig.email)}
          ${FormField(fieldConfig.phone)}
          <button type="submit">Send support request</button>
          <p class="status-message" id="form-status" aria-live="polite"></p>
        </form>
      `;
    }

    function App() {
      return `
        <section class="page-shell" aria-labelledby="support-title">
          <p class="eyebrow">Support</p>
          <h1 id="support-title">Contact our support team</h1>
          <p class="intro">Share your details and we’ll reach out with the fastest path to help.</p>
          ${ContactForm()}
        </section>
      `;
    }

    document.getElementById("root").innerHTML = App();

    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");
    let hasSubmitted = false;

    function getFieldMessages() {
      return {
        fullName: {
          invalid: "Error: Enter your full name."
        },
        email: {
          invalid: "Error: Enter a valid email address, such as name@example.com."
        },
        phone: {
          invalid: "Error: Enter a phone number using digits, spaces, dashes, parentheses, or a leading plus sign."
        }
      };
    }

    function getFieldError(input) {
      const value = input.value.trim();
      const messages = getFieldMessages();

      if (input.name === "fullName") {
        if (!value) {
          return messages.fullName.invalid;
        }
      }

      if (input.name === "email") {
        if (!value || !input.validity.valid) {
          return messages.email.invalid;
        }
      }

      if (input.name === "phone") {
        if (value && !/^\+?[\d\s().-]{7,20}$/.test(value)) {
          return messages.phone.invalid;
        }
      }

      return "";
    }

    function syncDescribedBy(input, showError) {
      const helpId = input.name === "phone" ? "phone-number-help" : "";
      const errorId = `${input.id}-error`;
      const describedByIds = [helpId, showError ? errorId : ""].filter(Boolean);

      if (describedByIds.length > 0) {
        input.setAttribute("aria-describedby", describedByIds.join(" "));
      } else {
        input.removeAttribute("aria-describedby");
      }
    }

    function clearFieldState(input) {
      const errorElement = document.getElementById(`${input.id}-error`);
      errorElement.textContent = "";
      errorElement.hidden = true;
      input.removeAttribute("aria-invalid");
      syncDescribedBy(input, false);
    }

    function setFieldState(input) {
      const errorElement = document.getElementById(`${input.id}-error`);
      const error = getFieldError(input);
      const hasError = Boolean(error);

      if (hasError) {
        errorElement.textContent = error;
        errorElement.hidden = false;
        input.setAttribute("aria-invalid", "true");
      } else {
        clearFieldState(input);
      }

      if (hasError) {
        syncDescribedBy(input, true);
      }
      return hasError;
    }

    function validateForm() {
      const inputs = Array.from(form.querySelectorAll("input"));
      const invalidInputs = inputs.filter((input) => setFieldState(input));
      return invalidInputs;
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      hasSubmitted = true;
      statusMessage.textContent = "";

      const invalidInputs = validateForm();

      if (invalidInputs.length > 0) {
        invalidInputs[0].focus();
        statusMessage.textContent = "Please correct the highlighted fields and try again.";
        return;
      }

      statusMessage.textContent = "Thanks. Your support request is ready to send.";
      form.reset();
      hasSubmitted = false;

      Array.from(form.querySelectorAll("input")).forEach((input) => {
        clearFieldState(input);
      });
    });

    form.addEventListener("input", (event) => {
      if (!(event.target instanceof HTMLInputElement)) {
        return;
      }

      if (hasSubmitted || event.target.getAttribute("aria-invalid") === "true") {
        setFieldState(event.target);
      }
    });

    form.addEventListener("focusout", (event) => {
      if (!(event.target instanceof HTMLInputElement)) {
        return;
      }

      if (hasSubmitted) {
        setFieldState(event.target);
      }
    });
  </script>
